#!/usr/bin/env python3
"""Copy the Church of Jesus Christ EMCOMM app module (templates/_shared/emcomm-app.js) into every page that uses it.

The module is the single source for Save to Outbox, Send to EOC, the EOC chooser and QR
scanning, the hand-off to an EOC server and the offline-app setup. Each page carries an
inlined copy (pages must work as single files: installed copies, the EOC server, the
portal) between these markers:

    <!-- EMCOMM-APP:BEGIN (generated by installer/sync-app-module.py; edit templates/_shared/emcomm-app.js) -->
    ...
    <!-- EMCOMM-APP:END -->

Run after editing the module:   python installer/sync-app-module.py
Exit code 1 if a page is missing its markers. --check exits 1 if any copy is out of date.
"""
import pathlib, re, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
# (tag, source, pages): the app module in the Worker forms and the portal; the map module in
# the EOC Message Center and the wall display (markers EMCOMM-MAP:BEGIN / END).
MODULES = [
    ('EMCOMM-APP', ROOT / 'templates' / '_shared' / 'emcomm-app.js', [
        ROOT / 'templates' / 'disaster-report' / 'Church_of_Jesus_Christ_Disaster_Report_Worker.html',
        ROOT / 'templates' / 'supply-order' / 'Church_of_Jesus_Christ_Supply_Order_Worker.html',
        ROOT / 'templates' / 'work-crew-log' / 'Church_of_Jesus_Christ_Work_Crew_Log_Worker.html',
        ROOT / 'forms' / 'index.html',
    ]),
    ('EMCOMM-MAP', ROOT / 'templates' / '_shared' / 'emcomm-map.js', [
        ROOT / 'eoc' / 'EOC_Message_Center.html',
        ROOT / 'eoc' / 'EOC_Wall_Display.html',
    ]),
]


def main():
    check = '--check' in sys.argv
    bad = 0
    for tag, src, pages in MODULES:
        begin = f'<!-- {tag}:BEGIN (generated by installer/sync-app-module.py; edit {src.relative_to(ROOT).as_posix()}) -->'
        end = f'<!-- {tag}:END -->'
        pattern = re.compile(r'<!-- ' + tag + r':BEGIN[^>]*-->.*?<!-- ' + tag + r':END -->', re.S)
        js = src.read_text(encoding='utf-8').rstrip() + '\n'
        block = begin + '\n<script>\n' + js + '</script>\n' + end
        for p in pages:
            text = p.read_text(encoding='utf-8')
            if not pattern.search(text):
                print(f'  MISSING markers: {p.relative_to(ROOT)} ({tag})')
                bad = 1
                continue
            new = pattern.sub(lambda _m: block, text, count=1)
            if new == text:
                print(f'  up to date: {p.relative_to(ROOT)} ({tag})')
            elif check:
                print(f'  OUT OF DATE: {p.relative_to(ROOT)} ({tag})')
                bad = 1
            else:
                with open(p, 'w', encoding='utf-8', newline='\n') as f:
                    f.write(new)
                print(f'  updated:    {p.relative_to(ROOT)} ({tag})')
    return bad


if __name__ == '__main__':
    sys.exit(main())
